import{c as s,Q as l,j as o,m as r}from"./chunks/framework.rWdQudnF.js";const p=JSON.parse('{"title":"软件架构概述","description":"","frontmatter":{"title":"软件架构概述"},"headers":[],"relativePath":"综合知识/架构设计/软件架构概述.md","filePath":"综合知识/架构设计/软件架构概述.md","lastUpdated":null}'),a={name:"综合知识/架构设计/软件架构概述.md"};function n(i,t,e,g,c,u){return l(),o("div",null,[...t[0]||(t[0]=[r('<h2 id="考点清单" tabindex="-1">考点清单 <a class="header-anchor" href="#考点清单" aria-label="Permalink to &quot;考点清单&quot;">​</a></h2><ul><li>[ ] 软件架构定义（结构/属性/交互）</li><li>[ ] 架构设计活动与生命周期</li><li>[ ] 多视图描述架构</li><li>[ ] 从需求模型→架构模型的转换</li><li>[ ] 架构设计主要作用与目标</li><li>[ ] 非功能性需求四分类</li><li>[ ] DSSA 三层模型</li><li>[ ] 构件组装失配类型</li><li>[ ] ES vs 一般系统 / DSS</li><li>[ ] 软件系统四项基本功能 + 三类硬件构件</li></ul><h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h3 id="一、软件架构定义-★" tabindex="-1">一、软件架构定义 ★ <a class="header-anchor" href="#一、软件架构定义-★" aria-label="Permalink to &quot;一、软件架构定义 ★&quot;">​</a></h3><blockquote><p>软件架构设计主要关注软件构件的<strong>结构</strong>、<strong>属性</strong>和<strong>交互作用</strong>，并通过多种<strong>视图</strong>全面描述特定系统的架构。</p></blockquote><ul><li><strong>结构</strong>：系统的组成构件</li><li><strong>属性</strong>：构件的特征描述</li><li><strong>交互作用</strong>：构件之间的协作关系</li><li><strong>视图</strong>：从不同视角描述架构的不同方面</li></ul><h3 id="二、架构设计活动-★" tabindex="-1">二、架构设计活动 ★ <a class="header-anchor" href="#二、架构设计活动-★" aria-label="Permalink to &quot;二、架构设计活动 ★&quot;">​</a></h3><p>架构设计是一个迭代过程，包括三大活动：</p><ol><li><strong>提出架构模型</strong> — 选择架构风格，建立初始架构</li><li><strong>产生架构设计</strong> — 将构件映射到架构，分析构件关系</li><li><strong>进行设计评审</strong> — 邀请独立外部人员评审</li></ol><blockquote><p>❌ 易错：架构设计活动<strong>不包含</strong>&quot;设计并实现这些构件&quot;（实现属于后续阶段）</p></blockquote><h3 id="三、架构设计生命周期" tabindex="-1">三、架构设计生命周期 <a class="header-anchor" href="#三、架构设计生命周期" aria-label="Permalink to &quot;三、架构设计生命周期&quot;">​</a></h3><table tabindex="0"><thead><tr><th>阶段</th><th>主要关注</th></tr></thead><tbody><tr><td><strong>需求分析</strong></td><td>需求获取、场景描述、质量属性定义</td></tr><tr><td><strong>设计阶段</strong></td><td>架构模型描述、设计分析方法、设计经验总结与复用</td></tr><tr><td><strong>实现阶段</strong></td><td>从架构向代码的过渡、开发过程支持、测试技术</td></tr><tr><td><strong>构件组装</strong></td><td>检测并解决架构失配问题</td></tr></tbody></table><h3 id="四、需求模型-→-架构模型转换-★" tabindex="-1">四、需求模型 → 架构模型转换 ★ <a class="header-anchor" href="#四、需求模型-→-架构模型转换-★" aria-label="Permalink to &quot;四、需求模型 → 架构模型转换 ★&quot;">​</a></h3><blockquote><p>两个核心问题：① <strong>如何构建架构模型</strong> ② <strong>如何保证模型转换的可追踪性</strong></p></blockquote><h3 id="五、架构设计的主要作用" tabindex="-1">五、架构设计的主要作用 <a class="header-anchor" href="#五、架构设计的主要作用" aria-label="Permalink to &quot;五、架构设计的主要作用&quot;">​</a></h3><ol><li>解决相对复杂的需求分析问题</li><li>解决<strong>非功能属性</strong>在系统占据重要位置的设计问题</li><li>解决生命周期长、扩展性需求高的系统整体结构问题</li></ol><blockquote><p>❌ 注意：架构设计<strong>不负责</strong>系统代码实现的具体细节</p></blockquote><h3 id="六、架构设计目标" tabindex="-1">六、架构设计目标 <a class="header-anchor" href="#六、架构设计目标" aria-label="Permalink to &quot;六、架构设计目标&quot;">​</a></h3><blockquote><p>软件架构设计的主要目标是获得一个同时满足<strong>功能性需求</strong>和<strong>非功能性需求</strong>的软件系统框架模型</p></blockquote><h3 id="七、非功能性需求四分类-★" tabindex="-1">七、非功能性需求四分类 ★ <a class="header-anchor" href="#七、非功能性需求四分类-★" aria-label="Permalink to &quot;七、非功能性需求四分类 ★&quot;">​</a></h3><table tabindex="0"><thead><tr><th>分类</th><th>含义</th><th>示例</th></tr></thead><tbody><tr><td><strong>操作性需求</strong></td><td>系统运行环境与变化</td><td>支持主流标准协议</td></tr><tr><td><strong>性能需求</strong></td><td>响应时间、吞吐量</td><td>响应 ≤ 3s</td></tr><tr><td><strong>安全性需求</strong></td><td>防中断、防数据丢失</td><td>密码加密、超时重登</td></tr><tr><td><strong>文化需求</strong></td><td>文化背景相关</td><td>多语言支持</td></tr></tbody></table><h3 id="八、dssa-特定领域软件架构-三层模型" tabindex="-1">八、DSSA（特定领域软件架构）三层模型 <a class="header-anchor" href="#八、dssa-特定领域软件架构-三层模型" aria-label="Permalink to &quot;八、DSSA（特定领域软件架构）三层模型&quot;">​</a></h3><blockquote><p>DSSA 是为一个特定应用领域中一组应用提供组织结构参考的标准软件体系结构</p></blockquote><p><strong>三层模型：</strong></p><ol><li><strong>领域开发环境</strong> — 顶层，领域设计人员工作环境</li><li><strong>领域特定应用开发环境</strong> — 中间层，应用开发人员工作环境</li><li><strong>应用执行环境</strong> — 底层，最终用户运行环境</li></ol><h3 id="九、构件组装失配类型-★" tabindex="-1">九、构件组装失配类型 ★ <a class="header-anchor" href="#九、构件组装失配类型-★" aria-label="Permalink to &quot;九、构件组装失配类型 ★&quot;">​</a></h3><table tabindex="0"><thead><tr><th>失配类型</th><th>原因</th></tr></thead><tbody><tr><td><strong>构件级失配</strong></td><td>对构件基础设施、控制模型、数据模型的假设冲突</td></tr><tr><td><strong>连接子级失配</strong></td><td>对构件交互协议、构件连接时数据格式的假设冲突</td></tr></tbody></table><blockquote><p>❌ 易错：不包括&quot;构件操作不当引起的失配&quot;</p></blockquote><h3 id="十、软件系统四项基本功能" tabindex="-1">十、软件系统四项基本功能 <a class="header-anchor" href="#十、软件系统四项基本功能" aria-label="Permalink to &quot;十、软件系统四项基本功能&quot;">​</a></h3><ol><li><strong>数据存储</strong> — 数据持久化存储与检索（data storage/persistence）</li><li><strong>数据访问逻辑</strong> — 处理数据的逻辑，通常是 SQL 查询</li><li><strong>应用逻辑（业务逻辑）</strong> — DFD、用例、功能需求中记录的逻辑</li><li><strong>表示逻辑</strong> — 用户界面显示与命令接收</li></ol><p><strong>三类主要硬件构件：</strong> 客户端、服务器、网络</p><h3 id="十一、es-与-dss" tabindex="-1">十一、ES 与 DSS <a class="header-anchor" href="#十一、es-与-dss" aria-label="Permalink to &quot;十一、ES 与 DSS&quot;">​</a></h3><ul><li><strong>专家系统（ES）</strong>：与一般系统的根本区别在于能<strong>解释推理过程</strong></li><li><strong>决策支持系统（DSS）</strong>：主要用于解决<strong>半结构化问题</strong></li></ul><h3 id="十二、设计经验重用技术" tabindex="-1">十二、设计经验重用技术 <a class="header-anchor" href="#十二、设计经验重用技术" aria-label="Permalink to &quot;十二、设计经验重用技术&quot;">​</a></h3><blockquote><p>用于总结和重用设计经验的主要技术：<strong>体系结构风格和DSSA</strong></p></blockquote><hr><h2 id="练习题" tabindex="-1">练习题 <a class="header-anchor" href="#练习题" aria-label="Permalink to &quot;练习题&quot;">​</a></h2><p><strong>[Q1] 软件架构概念（软件架构设计活动）</strong></p><p>软件架构设计包括提出架构模型、产生架构设计和进行设计评审等活动，是一个迭代的过程。架构设计主要关注软件组件的结构、属性和( )，并通过多种(请作答此空)_全面描述特定系统的架构。</p><ul><li><strong>A.</strong> 对象</li><li><strong>B.</strong> 代码</li><li><strong>C.</strong> 文档</li><li><strong>D.</strong> 视图</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>D</strong></p></div></details><hr><p><strong>[Q2] 软件架构概念（架构设计的目标）</strong></p><p>The objective of (请作答此空) is to determine what parts of the application software will be assigned to what hardware.</p><ul><li><strong>A.</strong> architecture design</li><li><strong>B.</strong> modular design</li><li><strong>C.</strong> physical design</li><li><strong>D.</strong> distribution design</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>A</strong></p></div></details><hr><p><strong>[Q3] 软件架构概念（需求细化）</strong></p><p>The first step is to refine the ( 请作答此空) into more detailed requirements.</p><ul><li><strong>A.</strong> functional requirements</li><li><strong>B.</strong> nonfunctional requirements</li><li><strong>C.</strong> system constraint</li><li><strong>D.</strong> system operational environment</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><hr><p><strong>[Q4] 软件架构概念（数据访问逻辑）</strong></p><p>The second function is the（请作答此空）,the processing required to access data.</p><ul><li><strong>A.</strong> data persistence数据持久化</li><li><strong>B.</strong> data access objects数据访问对象</li><li><strong>C.</strong> database connection数据库连接</li><li><strong>D.</strong> data access logic数据访问逻辑</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>D</strong></p></div></details><hr><p><strong>[Q5] 软件架构概念（构件关注点）</strong></p><p>软件架构设计主要关注软件构件的（ ）、属性和（请作答此空），并通过多种视图全面描述特定系统的架构。</p><ul><li><strong>A.</strong> 实现方式</li><li><strong>B.</strong> 交互作用</li><li><strong>C.</strong> 设计方案</li><li><strong>D.</strong> 测试方式</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><hr><p><strong>[Q6] 软件架构概念（错误描述）</strong></p><p>以下关于软件架构设计活动的描述，错误的是（）</p><ul><li><strong>A.</strong> 在建立软件架构的初期，一般需要选择一个合适的架构风格</li><li><strong>B.</strong> 将架构分析阶段已标识的构件映射到架构中，并分析这些构件之间的关系</li><li><strong>C.</strong> 软件架构设计活动将已标构件集成到软件架构中，设计并实现这些构件</li><li><strong>D.</strong> 一旦得到了详细的软件架构设计，需要邀请独立于系统开发的外部人员对系统进行评审</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><hr><p><strong>[Q7] 软件架构概念（DSSA三层模型）</strong></p><p>DSSA通常是一个具有三个层次的系统模型，包括（请作答此空）环境、领域特定应用开发环境和应用执行环境。</p><ul><li><strong>A.</strong> 领域需求</li><li><strong>B.</strong> 领域开发</li><li><strong>C.</strong> 领域执行</li><li><strong>D.</strong> 领域应用</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><hr><p><strong>[Q8] 软件架构概念（构件失配）</strong></p><p>在构件组装过程中需要检测并解决架构失配问题。其中 （1） 失配主要包括由于系统对构件基础设施、控制模型和数据模型的假设存在冲突引起的失配。</p><ul><li><strong>A.</strong> 构件</li><li><strong>B.</strong> 模型</li><li><strong>C.</strong> 协议</li><li><strong>D.</strong> 连接子</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>A</strong></p></div></details><hr><p><strong>[Q9] 软件架构概念（连接子失配）</strong></p><p>（2） 失配包括由于系统对构件交互协议、构件连接时数据格式的假设存在冲突引起的失配。</p><ul><li><strong>A.</strong> 构件</li><li><strong>B.</strong> 模型</li><li><strong>C.</strong> 协议</li><li><strong>D.</strong> 连接子</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>D</strong></p></div></details><hr><p><strong>[Q10] 软件架构概念（架构设计：硬件分配）</strong></p><p>The objective of （1） is to determine what parts of the application software will be assigned to what hardware.</p><ul><li><strong>A.</strong> architecture design</li><li><strong>B.</strong> modular design</li><li><strong>C.</strong> physical design</li><li><strong>D.</strong> distribution design</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>A</strong></p></div></details><hr><p><strong>[Q11] 软件架构概念（数据存储）</strong></p><p>The first is （2）. Most information systems require data to be stored and retrieved.</p><ul><li><strong>A.</strong> data access components</li><li><strong>B.</strong> database management system</li><li><strong>C.</strong> data storage</li><li><strong>D.</strong> data entities</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><hr><p><strong>[Q12] 软件架构概念（数据访问逻辑）</strong></p><p>The second function is the （3）, the processing required to access data.</p><ul><li><strong>A.</strong> data persistence</li><li><strong>B.</strong> data access objects</li><li><strong>C.</strong> database connection</li><li><strong>D.</strong> data access logic</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>D</strong></p></div></details><hr><p><strong>[Q13] 软件架构概念（应用逻辑）</strong></p><p>The third function is the （4）, which is the logic documented in the DFDs, use cases,and functional requirements.</p><ul><li><strong>A.</strong> system requirements</li><li><strong>B.</strong> system architecture</li><li><strong>C.</strong> application logic</li><li><strong>D.</strong> application program</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><hr><p><strong>[Q14] 软件架构概念（硬件构件）</strong></p><p>The three primary hardware components of a system are （5）.</p><ul><li><strong>A.</strong> computers,cables and network</li><li><strong>B.</strong> clients,servers,and network</li><li><strong>C.</strong> CPUs,memories and I/O devices</li><li><strong>D.</strong> CPUs,hard disks and I/O devices</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><hr><p><strong>[Q15] 软件架构概念（失配排除）</strong></p><p>在构件组装阶段失配问题主要不包括 （47） 。</p><ul><li><strong>A.</strong> 由构件引起的失配</li><li><strong>B.</strong> 由连接子引起的失配</li><li><strong>C.</strong> 由于系统成分对全局体系结构的假设存在冲突引起的失配</li><li><strong>D.</strong> 由构件操作不当引起的失配</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>D</strong></p></div></details><hr><p><strong>[Q16] 软件架构概念（非功能性需求：第一步）</strong></p><p>The first step is to refine the （1） into more detailed requirements.</p><ul><li><strong>A.</strong> functional requirements</li><li><strong>B.</strong> nonfunctional requirements</li><li><strong>C.</strong> system constraint</li><li><strong>D.</strong> system operational environment</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><hr><p><strong>[Q17] 软件架构概念（C/S架构）</strong></p><p>In a （2）, one also has to decide whether to use a two-tier, three-tier, or n-tier architecture.</p><ul><li><strong>A.</strong> client-based architecture</li><li><strong>B.</strong> server-based architecture</li><li><strong>C.</strong> network architecture</li><li><strong>D.</strong> client-server architecture</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>D</strong></p></div></details><hr><p><strong>[Q18] 软件架构概念（操作性需求）</strong></p><p>（3） specify the operating environment(s) in which the system must perform.</p><ul><li><strong>A.</strong> Operational requirements</li><li><strong>B.</strong> Speed requirement</li><li><strong>C.</strong> Access control requirements</li><li><strong>D.</strong> Customization requirements</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>A</strong></p></div></details><hr><p><strong>[Q19] 软件架构概念（性能需求）</strong></p><p>（4） focus on the nonfunctional requirements issues such as response time, capacity, and reliability.</p><ul><li><strong>A.</strong> Environment requirements</li><li><strong>B.</strong> Maintainability requirements</li><li><strong>C.</strong> Performance requirements</li><li><strong>D.</strong> Virus control requirements</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><hr><p><strong>[Q20] 软件架构概念（安全性需求）</strong></p><p>（5） are the abilities to protect the information system from disruption and data loss.</p><ul><li><strong>A.</strong> Safety requirements</li><li><strong>B.</strong> Security requirements</li><li><strong>C.</strong> Data management requirements</li><li><strong>D.</strong> System requirements</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><hr><p><strong>[Q21] 软件架构概念（结构）</strong></p><p>软件架构设计主要关注软件构件的（1）、属性和（2）。</p><ul><li><strong>A.</strong> 功能</li><li><strong>B.</strong> 实现</li><li><strong>C.</strong> 组成元素</li><li><strong>D.</strong> 结构</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>D</strong></p></div></details><hr><p><strong>[Q22] 软件架构概念（交互作用）</strong></p><p>软件架构设计主要关注软件构件的（1）、属性和（2）。</p><ul><li><strong>A.</strong> 实现方式</li><li><strong>B.</strong> 交互作用</li><li><strong>C.</strong> 设计方案</li><li><strong>D.</strong> 测试方式</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><hr><p><strong>[Q23] 软件架构概念（ES vs 一般系统）</strong></p><p>专家系统（ES）与一般计算机系统的根本区别在于 （ ） 。</p><ul><li><strong>A.</strong> 处理数字与符号</li><li><strong>B.</strong> 处理确定性知识</li><li><strong>C.</strong> 解释推理过程</li><li><strong>D.</strong> 操作成本低廉</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><hr><p><strong>[Q24] 软件架构概念（DSS）</strong></p><p>决策支持系统（DSS）主要用于解决 （ ） 。</p><ul><li><strong>A.</strong> 结构化问题</li><li><strong>B.</strong> 半结构化问题</li><li><strong>C.</strong> 日常事务处理</li><li><strong>D.</strong> 纯数据存储</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><hr><p><strong>[Q25] 软件架构概念（关注点）</strong></p><p>软件架构设计主要关注 （ ） 。</p><ul><li><strong>A.</strong> 构件的结构、属性及交互作用</li><li><strong>B.</strong> 编程语言语法规范</li><li><strong>C.</strong> 用户界面视觉设计</li><li><strong>D.</strong> 代码行数统计与优化</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>A</strong></p></div></details><hr><p><strong>[Q26] 软件架构概念（设计阶段排除）</strong></p><p>在设计阶段，软件架构设计的研究主要不包括 （ ） 。</p><ul><li><strong>A.</strong> 软件架构模型的描述</li><li><strong>B.</strong> 软件架构模型的设计与分析方法</li><li><strong>C.</strong> 对软件架构设计经验的总结与复用</li><li><strong>D.</strong> 从现有系统中获得需要的构件</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>D</strong></p></div></details><hr><p><strong>[Q27] 软件架构概念（架构设计作用）</strong></p><p>以下哪项不属于架构设计的主要作用（ ）。</p><ul><li><strong>A.</strong> 解决相对复杂的需求分析问题</li><li><strong>B.</strong> 解决非功能属性在系统占据重要位置的设计问题</li><li><strong>C.</strong> 解决系统代码实现的具体细节问题</li><li><strong>D.</strong> 解决生命周期长、扩展性需求高的系统整体结构问题</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><hr><p><strong>[Q28] 软件架构概念（实现阶段研究）</strong></p><p>在软件架构的实现阶段研究中，以下哪项不属于主要研究方向（ ）。</p><ul><li><strong>A.</strong> 基于软件架构的开发过程支持</li><li><strong>B.</strong> 从软件架构向实现过渡的途径</li><li><strong>C.</strong> 基于软件架构的测试技术</li><li><strong>D.</strong> 软件架构的多视图表示</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>D</strong></p></div></details><hr><p><strong>[Q29] 软件架构概念（需求→架构转换）</strong></p><p>在软件架构设计的需求阶段，关于需求模型向软件架构模型转换的主要关注点是（）。</p><ul><li><strong>A.</strong> 如何描述软件架构模型</li><li><strong>B.</strong> 如何分析软件架构质量属性</li><li><strong>C.</strong> 如何构建软件架构模型和保证可追踪性</li><li><strong>D.</strong> 如何选择合适的部署方案</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><hr><p><strong>[Q30] 软件架构概念（设计阶段关注）</strong></p><p>在软件架构设计的研究中，设计阶段主要关注哪些方面（ ）。</p><ul><li><strong>A.</strong> 需求分析和用户反馈</li><li><strong>B.</strong> 软件架构模型描述、设计与分析方法</li><li><strong>C.</strong> 代码实现和单元测试</li><li><strong>D.</strong> 系统部署和性能优化</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><hr><p><strong>[Q31] 软件架构概念（设计阶段）</strong></p><p>在软件架构设计生命周期中，哪个阶段主要关注软件架构模型的描述、设计与分析方法（ ）。</p><ul><li><strong>A.</strong> 需求分析阶段</li><li><strong>B.</strong> 设计阶段</li><li><strong>C.</strong> 实现阶段</li><li><strong>D.</strong> 构件组装阶段</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><hr><p><strong>[Q32] 软件架构概念（重用设计经验）</strong></p><p>在软件体系结构设计中，用于总结和重用设计经验的主要技术包括（）。</p><ul><li><strong>A.</strong> 设计模式和框架</li><li><strong>B.</strong> 体系结构风格和DSSA</li><li><strong>C.</strong> UML图和原型设计</li><li><strong>D.</strong> 代码重构和单元测试</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><hr><p><strong>[Q33] 软件架构概念（设计目标）</strong></p><p>软件架构设计的主要目标是获得一个满足什么需求的软件系统框架模型（ ）。</p><ul><li><strong>A.</strong> 只满足功能性需求</li><li><strong>B.</strong> 只满足非功能性需求</li><li><strong>C.</strong> 满足功能性需求和非功能性需求</li><li><strong>D.</strong> 满足用户界面需求</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><hr><p><strong>[Q34] 软件架构概念（模型转换）</strong></p><p>在从软件需求模型向软件架构模型转换时，需要特别关注的两个核心问题是 （ ） 。</p><ul><li><strong>A.</strong> 如何估算项目成本和如何分配开发任务</li><li><strong>B.</strong> 如何根据需求模型构建架构模型，以及如何保证模型转换的可追踪性</li><li><strong>C.</strong> 如何选择编程语言和如何设计数据库表</li><li><strong>D.</strong> 如何进行用户验收测试和如何编写用户手册</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details>',206)])])}const m=s(a,[["render",n]]);export{p as __pageData,m as default};
